from dataclasses import FrozenInstanceError, dataclass, replace


@dataclass(frozen=True, order=True)
class StudentRecord:
    student_id: str
    name: str
    score: int

    def __post_init__(self) -> None:
        object.__setattr__(self, "student_id", self.student_id.strip())
        object.__setattr__(self, "name", self.name.strip())
        if not self.student_id or not self.name:
            raise ValueError("student_id and name cannot be blank")
        if isinstance(self.score, bool) or not isinstance(self.score, int) or not 0 <= self.score <= 100:
            raise ValueError("score must be an integer from 0 to 100")


class RecordBook:
    def __init__(self) -> None:
        self._records: dict[str, StudentRecord] = {}

    def add(self, record: StudentRecord) -> bool:
        if record.student_id in self._records:
            return False
        self._records[record.student_id] = record
        return True

    def corrected_score(self, student_id: str, score: int) -> StudentRecord:
        old = self._records[student_id]
        corrected = replace(old, score=score)
        self._records[student_id] = corrected
        return corrected

    def ordered(self) -> tuple[StudentRecord, ...]:
        return tuple(sorted(self._records.values()))


def expect(error_type: type[BaseException], action) -> None:
    try:
        action()
    except error_type:
        return
    raise AssertionError(f"expected {error_type.__name__}")


def run_checks() -> None:
    amy = StudentRecord(" S02 ", " Amy ", 88)
    same = StudentRecord("S02", "Amy", 88)
    assert amy == same
    assert repr(amy) == "StudentRecord(student_id='S02', name='Amy', score=88)"
    expect(FrozenInstanceError, lambda: setattr(amy, "score", 90))

    book = RecordBook()
    assert book.add(amy)
    assert book.add(StudentRecord("S01", "林安", 0))
    assert not book.add(StudentRecord("S01", "Other", 60))
    corrected = book.corrected_score("S02", 91)
    assert amy.score == 88 and corrected.score == 91
    assert [r.student_id for r in book.ordered()] == ["S01", "S02"]

    expect(ValueError, lambda: StudentRecord("", "Bo", 70))
    expect(ValueError, lambda: StudentRecord("S03", "Bo", True))
    expect(ValueError, lambda: book.corrected_score("S02", 101))
    expect(KeyError, lambda: book.corrected_score("missing", 80))


if __name__ == "__main__":
    run_checks()
    print("dataclass-record checks: OK")
